        rings.forEach(function(r){if(!r||!r.length)return;var minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;r.forEach(function(pt){minX=Math.min(minX,pt[0]);maxX=Math.max(maxX,pt[0]);minY=Math.min(minY,pt[1]);maxY=Math.max(maxY,pt[1]);});var area=(maxX-minX)*(maxY-minY);if(area>bestArea){bestArea=area;best=[(minX+maxX)/2,(minY+maxY)/2];}});
