        var ex=r.left+r.width/2, ey=r.top+r.height/2, dx=ax-ex, dy=ay-ey, horizontal=Math.abs(dx)>Math.abs(dy);
        el.style.setProperty('--dx',dx.toFixed(1)+'px'); el.style.setProperty('--dy',dy.toFixed(1)+'px');
        el.style.setProperty('--rx',horizontal?'0deg':(dy>0?'-74deg':'74deg')); el.style.setProperty('--ry',horizontal?(dx>0?'74deg':'-74deg'):'0deg');
