        var r=el.getBoundingClientRect(); if(!r.width||!r.height)return;
        var ex=r.left+r.width/2, ey=r.top+r.height/2, dx=sx-ex, dy=sy-ey, horizontal=Math.abs(dx)>Math.abs(dy);
