        el.style.setProperty('--frx',horizontal?'0deg':(dy>0?'-70deg':'70deg')); el.style.setProperty('--fry',horizontal?(dx>0?'70deg':'-70deg'):'0deg'); el.style.setProperty('--fdelay',(index*34)+'ms');
