        regions.forEach(function(region,ri){DATASET.months.forEach(function(month,mi){var f={region:region,country:'All Countries'}; if(this._filters.region!=='All Regions'&&this._filters.region!==region)return; var c=metricValue(filteredRows('Current',f).filter(function(r){return r.month===month;}),this._selectedMetric), p=metricValue(filteredRows('Previous',f).filter(function(r){return r.month===month;}),this._selectedMetric), ch=p?pctChange(c,p):0; min=Math.min(min,ch||0);max=Math.max(max,ch||0);values.push([mi,ri,ch||0]);},this);},this);
