      current.forEach(function(r){var n=r.dims[dimensionKey]||'Other';if(!map[n])map[n]={name:n,current:0,previous:0};map[n].current+=r.measures[metricKey]||0;});
      previous.forEach(function(r){var n=r.dims[dimensionKey]||'Other';if(!map[n])map[n]={name:n,current:0,previous:0};map[n].previous+=r.measures[metricKey]||0;});
